package com.nook.service; import com.nook.application.port.out.PushNotificationPort; import com.nook.domain.SocialEntities.*; import com.nook.dto.ApiDtos.*; import com.nook.exception.ApiException; import com.nook.mapper.SocialMapper; import com.nook.repository.SocialRepository; import jakarta.persistence.EntityManager; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class ConversationService {final SocialRepository repo;final SocialMapper mapper;final EntityManager em;final AuditService audit;final PushNotificationPort push;public ConversationService(SocialRepository r,SocialMapper m,EntityManager e,AuditService audit,PushNotificationPort push){repo=r;mapper=m;em=e;this.audit=audit;this.push=push;}void guard(UUID c,UUID u){if(!repo.conversationMember(c,u))throw new ApiException(HttpStatus.FORBIDDEN,"NOT_MATCHED","El chat requiere un match activo");}public List<ConversationDto> list(UUID me){return repo.conversations(me).stream().map(c->{Match m=repo.find(Match.class,c.matchId);UUID o=m.userOneId.equals(me)?m.userTwoId:m.userOneId;String last=repo.messages(c.id,0,1).stream().findFirst().map(x->x.body).orElse("");return new ConversationDto(c.id,c.matchId,mapper.profile(me,repo.profile(o)),last,c.updatedAt);}).toList();}public PageDto<MessageDto> messages(UUID me,UUID c,int page,int size){guard(c,me);List<Message> x=repo.messages(c,page,size+1);return new PageDto<>(x.stream().limit(size).map(m->new MessageDto(m.id,m.senderId,m.body,m.messageType,m.createdAt)).toList(),page,size,x.size()>size);}@Transactional public MessageDto send(UUID me,UUID c,String body,UUID clientId){guard(c,me);Conversation v=repo.find(Conversation.class,c);repo.lock(v);Message existing=repo.messageByClientId(c,clientId).orElse(null);if(existing!=null)return new MessageDto(existing.id,existing.senderId,existing.body,existing.messageType,existing.createdAt);Message m=new Message();m.conversationId=c;m.senderId=me;m.clientMessageId=clientId;m.body=body.trim();repo.save(m);v.updatedAt=Instant.now();Match match=repo.find(Match.class,v.matchId);UUID other=match.userOneId.equals(me)?match.userTwoId:match.userOneId;push.deliver(other,"MESSAGE",repo.profile(me).name,m.body,c);audit.record(me,"MESSAGE_SENT","MESSAGE",m.id);return new MessageDto(m.id,me,m.body,m.messageType,m.createdAt);} }
